-- LIMIT / OFFSET operands: OP_MustBeInt ('abc', 1.5, NULL, blobs raise
-- "datatype mismatch"; '1e1' is 10), no column references (not even an
-- enclosing query's), and scalar / EXISTS subqueries read LIMIT (X <> 0)
-- (sqlite3CodeSubselect) — LIMIT 1 when absent.
CREATE TABLE lt(x INTEGER);
INSERT INTO lt VALUES (1),(2),(3);
SELECT x FROM lt LIMIT 'abc';
SELECT x FROM lt LIMIT 1.5;
SELECT x FROM lt LIMIT 2.0;
SELECT x FROM lt LIMIT '2';
SELECT x FROM lt LIMIT ' 2 ';
SELECT x FROM lt LIMIT -1;
SELECT x FROM lt LIMIT NULL;
SELECT x FROM lt LIMIT x'01';
SELECT x FROM lt LIMIT 2 OFFSET 'abc';
SELECT x FROM lt LIMIT 2 OFFSET 1.5;
SELECT x FROM lt LIMIT 2 OFFSET -5;
SELECT x FROM lt LIMIT 2 OFFSET NULL;
SELECT x FROM lt LIMIT 0 OFFSET 'abc';
SELECT x FROM lt LIMIT 1e3;
SELECT x FROM lt LIMIT '1e1';
SELECT x FROM lt LIMIT '0x10';
SELECT x FROM lt LIMIT x;
SELECT x FROM lt LIMIT lt.x;
CREATE TABLE t(x INTEGER, f INTEGER);
INSERT INTO t VALUES (1, 1),(2, -9223372036854775808),(3, 3);
CREATE TABLE s(k TEXT);
INSERT INTO s VALUES ('0'),(' 0'),('abc'),('2');
SELECT (SELECT x FROM t LIMIT 'abc');
SELECT (SELECT x FROM t LIMIT 1.5);
SELECT (SELECT x FROM t LIMIT -1);
SELECT (SELECT x FROM t LIMIT 0);
SELECT (SELECT x FROM t LIMIT '0');
SELECT (SELECT x FROM t LIMIT ' 0');
SELECT (SELECT x FROM t LIMIT NULL);
SELECT (SELECT x FROM t LIMIT 2 OFFSET 1);
SELECT (SELECT x FROM t LIMIT 2 OFFSET 'abc');
SELECT (SELECT abs(f) FROM t);
SELECT EXISTS (SELECT 1 FROM t LIMIT 'abc');
SELECT EXISTS (SELECT 1 FROM t LIMIT 0);
SELECT EXISTS (SELECT abs(f) FROM t);
SELECT k, (SELECT x FROM t LIMIT s.k) FROM s;
SELECT k, EXISTS (SELECT 1 FROM t LIMIT s.k) FROM s;
SELECT k, (SELECT x FROM t WHERE x > 1 LIMIT s.k OFFSET 1) FROM s;
SELECT x FROM t WHERE x = (SELECT x FROM t ORDER BY x DESC LIMIT 'q');
SELECT x, (SELECT abs(f) FROM t AS u WHERE u.x >= t.x) FROM t;
SELECT k, (SELECT x FROM t LIMIT s.k) FROM s;
SELECT x FROM t LIMIT (SELECT count(*) FROM s);
